const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const allOrders = $input.all().map(i => i.json);
const orders = allOrders.filter(o => new Date(o.created_at).getTime() < cutoff);
const rows = orders.map(o => {
  const ph = o.users || {};
  const date = new Date(o.created_at).toLocaleDateString('fr-FR');
  const ref = o.id.slice(0,8).toUpperCase();
  const total = (o.total || 0).toFixed(2);
  const name = ph.name || ph.email || '?';
  return `<tr><td style='padding:8px;border:1px solid #ddd'>${ref}</td><td style='padding:8px;border:1px solid #ddd'>${date}</td><td style='padding:8px;border:1px solid #ddd'>${name}</td><td style='padding:8px;border:1px solid #ddd'>${total} MAD</td></tr>`;
}).join('');
return [{ json: { staleCount: orders.length, staleRows: rows } }];

const stale = $('Traiter commandes en attente').first().json;
const stock = $('Stock faible').all().map(i => i.json);
const stockRows = stock.map(p => {
  const color = p.stock_quantity < 10 ? 'red' : '#e67e22';
  return `<tr><td style='padding:8px;border:1px solid #ddd'>${p.name}</td><td style='padding:8px;border:1px solid #ddd;color:${color}'>${p.stock_quantity} unites</td></tr>`;
}).join('');
const hasContent = stale.staleCount > 0 || stock.length > 0;
const today = new Date().toLocaleDateString('fr-FR', {weekday:'long', year:'numeric', month:'long', day:'numeric'});
let html = `<div style='font-family:Arial,sans-serif;max-width:600px;margin:0 auto'><div style='background:#1a472a;color:white;padding:20px;text-align:center'><h1>Digest Quotidien Neoval Pharma</h1><p>${today}</p></div>`;
if (stale.staleCount > 0) {
  html += `<div style='padding:20px'><h2 style='color:#c0392b'>Commandes en attente +24h (${stale.staleCount})</h2><table style='width:100%;border-collapse:collapse'><thead><tr style='background:#f5f5f5'><th style='padding:8px;text-align:left;border:1px solid #ddd'>Ref</th><th style='padding:8px;border:1px solid #ddd'>Date</th><th style='padding:8px;border:1px solid #ddd'>Pharmacie</th><th style='padding:8px;border:1px solid #ddd'>Total</th></tr></thead><tbody>${stale.staleRows}</tbody></table></div>`;
}
if (stock.length > 0) {
  html += `<div style='padding:20px'><h2 style='color:#e67e22'>Stock faible (${stock.length} produits)</h2><table style='width:100%;border-collapse:collapse'><thead><tr style='background:#f5f5f5'><th style='padding:8px;text-align:left;border:1px solid #ddd'>Produit</th><th style='padding:8px;border:1px solid #ddd'>Quantite</th></tr></thead><tbody>${stockRows}</tbody></table></div>`;
}
if (!hasContent) {
  html += '<div style="padding:20px;color:green;text-align:center"><p>Tout est en ordre - aucune alerte.</p></div>';
}
html += '</div>';
const subject = '[Neoval] Digest ' + today + (stale.staleCount > 0 ? ' - ' + stale.staleCount + ' commande(s) en attente' : '') + (stock.length > 0 ? ' - ' + stock.length + ' alerte(s) stock' : '');
return [{ json: { hasContent, subject, html } }];
